import fs from 'fs';
import path from 'path';

/**
 * Inlines critical CSS into static HTML files to eliminate render-blocking stylesheet requests
 * and flatten the network dependency tree.
 * Keeps non-blocking asynchronous stylesheet links so client-side navigation and browser caching work seamlessly.
 */
export function inlineCssForHtml(htmlPath) {
    if (!fs.existsSync(htmlPath)) return;

    let html = fs.readFileSync(htmlPath, 'utf8');

    // Find all stylesheet links generated by Next.js
    const linkRegex = /<link rel="stylesheet" href="([^"]+)" data-precedence="next"\/>/g;
    const matches = [...html.matchAll(linkRegex)];

    if (matches.length === 0) return;

    const cssHrefs = matches.map(m => m[1]);
    let combinedCss = '';

    for (const href of cssHrefs) {
        // Resolve absolute path in out/
        const relativeHref = href.startsWith('/') ? href.slice(1) : href;
        const filePath = path.join('out', relativeHref);
        if (fs.existsSync(filePath)) {
            const css = fs.readFileSync(filePath, 'utf8');
            combinedCss += css + '\n';
        }
    }

    if (!combinedCss) return;

    // Clean and minify inlined CSS
    const minifiedCss = combinedCss
        .replace(/\/\*[\s\S]*?\*\//g, '') // remove comments
        .replace(/\s+/g, ' ')             // collapse whitespace
        .replace(/\s*([{};:,>+~])\s*/g, '$1') // remove spaces around syntax
        .trim();

    const styleTag = `<style id="__bb_critical_css">${minifiedCss}</style>`;

    // Replace the first stylesheet link with the inlined style + non-blocking links
    let replacedFirst = false;
    html = html.replace(linkRegex, (fullMatch, href) => {
        const nonBlockingLink = `<link rel="stylesheet" href="${href}" data-precedence="next" media="print" onload="this.media='all'"/><noscript><link rel="stylesheet" href="${href}" data-precedence="next"/></noscript>`;
        if (!replacedFirst) {
            replacedFirst = true;
            return `${styleTag}\n${nonBlockingLink}`;
        }
        return nonBlockingLink;
    });

    fs.writeFileSync(htmlPath, html, 'utf8');
    console.log(`Inlined ${minifiedCss.length} bytes of critical CSS into ${htmlPath}`);
}

async function run() {
    console.log('--- Inlining Critical CSS for Homepage & Landing Routes ---');
    const targetHtmls = [
        'out/index.html',
        'out/menu/index.html',
        'out/visit/index.html',
    ];

    for (const h of targetHtmls) {
        inlineCssForHtml(h);
    }
    console.log('--- Critical CSS Inlining Complete ---');
}

// Run directly if invoked as CLI
if (process.argv[1] && process.argv[1].endsWith('inline-critical-css.mjs')) {
    run();
}
